package com.pcguard.controller;
import com.pcguard.service.MonitoringService; import java.util.*; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController @RequestMapping("/api/v1") @CrossOrigin(origins = {"http://localhost:5173","http://localhost:5174","http://127.0.0.1:5173","http://127.0.0.1:5174"}, methods = {RequestMethod.GET,RequestMethod.POST,RequestMethod.OPTIONS,RequestMethod.DELETE}, allowedHeaders = "*", maxAge = 3600) public class MonitoringController { private final MonitoringService s; public MonitoringController(MonitoringService s){this.s=s;} @GetMapping("/computers") public Object computers(){return s.computers();} @GetMapping("/computers/{id}") public Object computer(@PathVariable Long id){return s.computer(id);} @DeleteMapping("/computers/{id}") public Object deleteComputer(@PathVariable Long id){s.deleteComputer(id);return Map.of("deleted",true,"id",id);} @GetMapping("/computers/{id}/telemetry") public Object telemetry(@PathVariable Long id){return s.telemetry(id);} @GetMapping("/computers/{id}/faults") public Object faultsForComputer(@PathVariable Long id){return s.faults(id);} @GetMapping("/computers/{id}/reports") public Object reportsForComputer(@PathVariable Long id){return s.reports(id);} @GetMapping("/faults") public Object faults(@RequestParam(required=false) Long computerId){return s.faults(computerId);} @GetMapping("/reports") public Object reports(@RequestParam(required=false) Long computerId){return s.reports(computerId);} @GetMapping("/dashboard/summary") public Object summary(){return s.summary();} @GetMapping(value="/events",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public SseEmitter events(){return s.stream();} @GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP");} }
